import{_ as t,a,o,a2 as r}from"./chunks/framework.DCcmcJcL.js";const p=JSON.parse('{"title":"Personalized Checkout Message","description":"","frontmatter":{},"headers":[],"relativePath":"generative-ai/checkout-message.md","filePath":"generative-ai/checkout-message.md","lastUpdated":1789441803000}'),s={name:"generative-ai/checkout-message.md"};function n(i,e,h,d,l,c){return o(),a("div",null,e[0]||(e[0]=[r('<h1 id="personalized-checkout-message" tabindex="-1">Personalized Checkout Message <a class="header-anchor" href="#personalized-checkout-message" aria-label="Permalink to &quot;Personalized Checkout Message&quot;">​</a></h1><div class="feature-meta feature--ai"><span class="feature-meta__primary">Generative AI</span><span>Storefront</span></div><p>After an order is placed, the order confirmation page shows <strong>Thank you for your order!</strong> and a standard line: &quot;We will email you, your order details and tracking information&quot;. With the personalized checkout message on, Magic AI writes a short thank-you message for that order and shows it in place of the standard line. It gives the moment a personal touch, with no work on your side.</p><h2 id="where-it-appears" tabindex="-1">Where it appears <a class="header-anchor" href="#where-it-appears" aria-label="Permalink to &quot;Where it appears&quot;">​</a></h2><p>On the order confirmation page, under <strong>Thank you for your order!</strong>, straight after checkout.</p><h2 id="how-the-message-is-written" tabindex="-1">How the message is written <a class="header-anchor" href="#how-the-message-is-written" aria-label="Permalink to &quot;How the message is written&quot;">​</a></h2><ol><li>A shopper places an order.</li><li>When the confirmation page opens, Bagisto sends the model the order&#39;s details: each item&#39;s name, quantity and total, the customer&#39;s name, the storefront language and your store&#39;s name.</li><li>The model&#39;s message is shown as plain text in place of the standard line.</li></ol><p>If the provider can&#39;t be reached, the page shows the standard line and the order isn&#39;t affected.</p><div class="tip custom-block"><p class="custom-block-title">Try it before shoppers see it</p><p>The message isn&#39;t checked before the shopper sees it. Place a few test orders after you switch the feature on, and read the messages they get.</p></div><h3 id="the-message-is-written-once-and-not-stored" tabindex="-1">The message is written once and not stored <a class="header-anchor" href="#the-message-is-written-once-and-not-stored" aria-label="Permalink to &quot;The message is written once and not stored&quot;">​</a></h3><ul><li><strong>The confirmation page waits for the model&#39;s reply before it opens</strong>, so choose a fast model.</li><li><strong>The message isn&#39;t saved with the order</strong> and isn&#39;t included in order emails.</li><li><strong>The confirmation page is shown only once.</strong> If the shopper reloads it, they&#39;re taken to the cart.</li><li><strong>Only the order&#39;s own details are used</strong>, nothing the shopper hasn&#39;t shared with your store.</li></ul><h2 id="what-you-control" tabindex="-1">What you control <a class="header-anchor" href="#what-you-control" aria-label="Permalink to &quot;What you control&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Setting</th><th>What it does</th></tr></thead><tbody><tr><td><strong>Enabled</strong> under <strong>Configure &gt;&gt; Magic AI &gt;&gt; General</strong></td><td>Switches every Magic AI feature on or off</td></tr><tr><td><strong>Enabled</strong> in the <strong>Personalized Checkout Message</strong> section of <strong>Configure &gt;&gt; Magic AI &gt;&gt; Storefront Features</strong></td><td>Turns the message on, per channel</td></tr><tr><td><strong>Model</strong> in the <strong>Personalized Checkout Message</strong> section</td><td>The model that writes the message, per channel</td></tr></tbody></table><p>To set everything up, see <a href="./../configure/magic-ai.html#enable-the-storefront-features">Enable the storefront features</a>.</p><p>Each order confirmation is one request to the provider, billed by that provider.</p>',15)]))}const u=t(s,[["render",n]]);export{p as __pageData,u as default};
